async function comparisonAxe(page:Page,name:string,details:any){
 if(!await page.evaluate(()=>!!(window as any).axe))await page.addScriptTag({path:join(ROOT,'node_modules','axe-core','axe.min.js')});
 const violations=await page.evaluate(async()=>{const result=await (window as any).axe.run(document.querySelector('[data-testid="maine-sld-panel"]'),{resultTypes:['violations']});return result.violations.map((v:any)=>({id:v.id,impact:v.impact,nodes:v.nodes.map((n:any)=>n.html)}));});
 await writeFile(join(REPORT,name+'.json'),JSON.stringify({...details,violations},null,2));expect(violations).toEqual([]);
}

