const planningEscape=(text:string)=>text.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
async function openPlanningReview(page:Page){const planning=page.getByTestId('participant-planning-review');if(await planning.getAttribute('open')===null){await planning.locator('summary').focus();await page.keyboard.press('Enter');}await expect(planning).toHaveAttribute('open','');return planning;}
async function planningWritingFeedback(page:Page,fieldId:string,counterId:string){const field=page.getByTestId(fieldId),counter=page.getByTestId(counterId),descriptionId='msld-'+counterId;await expect(field).toHaveAttribute('maxlength','4000');await expect(counter).toHaveAttribute('id',descriptionId);expect((await field.getAttribute('aria-describedby')||'').split(/\s+/)).toContain(descriptionId);const count=(await field.inputValue()).length;await expect(counter).toContainText(count.toLocaleString('en-US')+' / 4,000 characters');expect(await counter.getAttribute('aria-live')||'').not.toMatch(/polite|assertive/);await expect(counter).not.toHaveAttribute('role',/status|alert/);}

