const saveFailureMessage='Tab saving is unavailable. Your current work is still available in this open activity. Download a worksheet before closing or refreshing.';
const saveRecoveryMessage='Tab saving is available again. Your current work is saved for this tab.';
const saveRetryFailureMessage='Tab saving is still unavailable. Download a worksheet before closing or refreshing.';
async function installSaveRecoveryFixture(page:Page,mode:'blocked'|'quota'|'okay'){
 await page.addInitScript(initial=>{
  const nativeStorage=window.sessionStorage,nativeSet=Storage.prototype.setItem;
  (window as any).__sldSaveMode=initial;(window as any).__sldSaveWrites=[];(window as any).__sldAnnouncementStrings=[];(window as any).__sldNativeFeedbackTexts=[];
  Object.defineProperty(window,'sessionStorage',{configurable:true,get(){if((window as any).__sldSaveMode==='blocked')throw new DOMException('Session storage access blocked','SecurityError');return nativeStorage;}});
  Storage.prototype.setItem=function(key,value){if(this===nativeStorage&&key==='alloflow_sld_case_lab_session_v1'){if((window as any).__sldSaveMode==='quota')throw new DOMException('Session storage full','QuotaExceededError');(window as any).__sldSaveWrites.push(JSON.parse(value));}return nativeSet.call(this,key,value);};
 },mode);
}
async function mountSaveRecovery(page:Page,theme:string,announce:boolean,expiredState?:any){
 await page.goto(base+'/__host?tool=maine-sld-practice&case=alex');
 await page.evaluate(({theme,announce,expiredState})=>{
  if(expiredState)window.sessionStorage.setItem('alloflow_sld_case_lab_session_v1',JSON.stringify({at:Date.now()-43200001,moduleVersion:'1.1.0',state:expiredState}));
  if(announce){const panel=(window as any).AlloModules.MaineSldPractice.MaineSldPracticePanel;(window as any).AlloModules.MaineSldPractice.MaineSldPracticePanel=function(props:any){return (window as any).React.createElement(panel,{...props,announceToSR:(message:string)=>(window as any).__sldAnnouncementStrings.push(message)});};}
  (window as any).__mount(theme);
 },{theme,announce,expiredState});
 await expect(page.getByTestId('maine-sld-panel')).toBeVisible();
}
async function saveAnnouncementCount(page:Page,message:string,native=false){return page.evaluate(({message,native})=>((window as any)[native?'__sldNativeFeedbackTexts':'__sldAnnouncementStrings']||[]).filter((value:string)=>value===message).length,{message,native});}
async function downloadSaveWorksheet(page:Page,action:any,name:string){const pending=page.waitForEvent('download');await action.click();const file=await pending,path=join(REPORT,name);await file.saveAs(path);return JSON.parse(await readFile(path,'utf8'));}
function assertSaveWorksheetSchema(worksheet:any,caseIds:string[]){expect(Object.keys(worksheet).sort()).toEqual(['activeCase','caseWork','exportedAt','format','moduleVersion','reviewed','schemaVersion'].sort());expect(worksheet.format).toBe('alloflow-maine-sld-practice');expect(worksheet.schemaVersion).toBe(1);expect(worksheet.moduleVersion).toBe('1.1.0');expect(Object.keys(worksheet.caseWork).sort()).toEqual([...caseIds].sort());for(const work of Object.values(worksheet.caseWork)){expect(Object.keys(work as any).sort()).toEqual(['checkAnswers','checkSubmitted','debriefRevealed','findings','reflections','responses'].sort());expect(Object.keys((work as any).responses).sort()).toEqual(Array.from({length:9},(_,index)=>'Q'+(index+1)).sort());expect(Object.keys((work as any).reflections).sort()).toEqual(['caution','access','sdi','summary','gap','family','multilingual'].sort());}}

