// Guide-origin editing uses the existing response fields and transient return UI.
const guideRevisionQuestions=Array.from({length:9},(_,index)=>'Q'+(index+1));
async function guideRevisionReveal(page:Page){
 await step(page,'debrief');
 if(await page.getByTestId('reveal-debrief').count())await page.getByTestId('reveal-debrief').click();
 await expect(page.getByRole('heading',{name:/^Suggested reasoning/})).toBeVisible();
 await expect(page.locator('[data-testid^="revise-guide-"]')).toHaveCount(9);
}
async function guideRevisionDownload(page:Page,name:string){
 const pending=page.waitForEvent('download');await worksheetAction(page,page.getByTestId('export-reflection'));
 const file=await pending,path=join(REPORT,name);await file.saveAs(path);return JSON.parse(await readFile(path,'utf8'));
}
async function guideRevisionRestore(page:Page,worksheet:any){
 await page.locator('input[type=file]').setInputFiles({name:'guide-revision-seed.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(worksheet))});
 await page.getByRole('alertdialog').getByRole('button',{name:'Restore worksheet',exact:true}).click();
}
function guideRevisionNoSerializedReturn(value:any){
 if(!value||typeof value!=='object')return;
 for(const [key,entry] of Object.entries(value)){
  expect(['participantReturn','guideQuestion','guideReturn','pendingParticipantReview','pendingGuide','returnContext','evidenceReturn','comparisonReturn','earlierOpen','planningOpen']).not.toContain(key);
  guideRevisionNoSerializedReturn(entry);
 }
}
async function guideRevisionNoReturnUI(page:Page){
 for(const id of ['guide-review-return','return-to-reviewed-guide','participant-review-return','evidence-return'])await expect(page.getByTestId(id)).toHaveCount(0);
 await expect(page.locator('[data-testid^="guide-return-"]')).toHaveCount(0);
}
async function guideRevisionOrigin(page:Page,question:string,title:string){
 const lower=question.toLowerCase();
 await expect(page.getByTestId('guide-review-return')).toBeVisible();
 await expect(page.getByTestId('participant-review-return')).toHaveCount(0);
 await expect(page.locator('[data-testid^="guide-return-"]')).toHaveCount(1);
 for(const id of ['return-to-reviewed-guide','guide-return-'+lower]){
  await expect(page.getByTestId(id)).toHaveText('Return to '+question+' guide');
  await expect(page.getByTestId(id)).toHaveAccessibleName('Return to reviewed '+question+' guide for '+title);
 }
}

