// Single-slot finding recovery is transient; participant worksheet fields remain unchanged.
const findingRemovalNote=(caseId:string)=>{const begin='  Participant '+caseId+' finding evidence.\n<b data-finding-removal="literal">Keep this as text</b>\n',end='\nRemaining uncertainty.  ';return begin+'R'.repeat(4000-begin.length-end.length)+end;};
const findingRemovalContext=(fixture:any,index:number)=>({id:'context-'+index,label:typeof fixture.narrative[index]==='string'?fixture.narrative[index]:fixture.narrative[index].body||fixture.narrative[index].text||'',test:'Case record'});
async function findingRemovalDownload(page:Page,name:string){const pending=page.waitForEvent('download');await worksheetAction(page,page.getByTestId('export-reflection'));const file=await pending;const path=join(REPORT,name);await file.saveAs(path);return {worksheet:JSON.parse(await readFile(path,'utf8')),payload:{name,mimeType:'application/json',buffer:await readFile(path)}};}
async function findingRemovalRestore(page:Page,payload:any){await page.locator('input[type=file]').setInputFiles(payload);await page.getByRole('alertdialog').getByRole('button',{name:'Restore worksheet',exact:true}).click();}
async function findingRemovalAssertRecovery(page:Page,row:any,fixture:any){const recovery=page.getByTestId('finding-removal-recovery');await expect(recovery).toBeVisible();await expect(recovery.getByTestId('undo-finding-removal')).toHaveAccessibleName('Undo removal of '+row.label+' · '+(row.test||'Unspecified assessment')+' · '+fixture.title);return recovery;}
function findingRemovalNoSerializedRecovery(value:any){if(!value||typeof value!=='object')return;for(const [key,item] of Object.entries(value)){expect(key).not.toMatch(/undo|removal|recovery|removedFinding/i);findingRemovalNoSerializedRecovery(item);}}
async function findingRemovalSeed(page:Page,data:any){const initial=await findingRemovalDownload(page,'finding-removal-blank-worksheet.json');const worksheet=initial.worksheet;for(const fixture of data.cases){for(let index=0;index<Math.min(3,fixture.narrative.length);index++)worksheet.caseWork[fixture.id].findings['context-'+index]={purpose:index===0?'supporting':'complicating',note:index===0?findingRemovalNote(fixture.id):'Participant '+fixture.id+' context '+index+' must retain its role and literal note.\n<em>Text only.</em>'};worksheet.caseWork[fixture.id].responses.Q9={answer:'more',note:'Participant '+fixture.id+' existing Q9 reasoning remains independent.'};}worksheet.activeCase='alex';const payload={name:'finding-removal-seed.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(worksheet))};await writeFile(join(REPORT,'finding-removal-seed.json'),payload.buffer);await findingRemovalRestore(page,payload);return {worksheet,payload};}
async function findingRemovalFocusVisible(page:Page,id:string){await expect(page.getByTestId(id)).toBeFocused();const bounds=await page.getByTestId(id).evaluate(node=>{const main=document.querySelector('.msld-main')!.getBoundingClientRect(),field=node.getBoundingClientRect();return {mainTop:main.top,mainBottom:main.bottom,fieldTop:field.top,fieldBottom:field.bottom};});expect(bounds.fieldTop).toBeGreaterThanOrEqual(bounds.mainTop-1);expect(bounds.fieldBottom).toBeLessThanOrEqual(bounds.mainBottom+1);}
async function findingRemovalAxe(page:Page,name:string,state:any){await page.addScriptTag({path:join(ROOT,'node_modules','axe-core','axe.min.js')});const violations=await page.evaluate(async()=>{const result=await (window as any).axe.run(document.querySelector('[data-testid="maine-sld-panel"]'),{resultTypes:['violations']});return result.violations.map((item:any)=>({id:item.id,impact:item.impact,nodes:item.nodes.map((node:any)=>node.html)}));});await writeFile(join(REPORT,name),JSON.stringify({...state,violations},null,2));expect(violations).toEqual([]);}

